pub fn pk_parse_engines(b: &[u8], from: i32, to: i32, mut out: &mut crate::port::Cells, mut msg: &mut String) -> i32 {
    // Read a comma-separated list of engine names (`tesseract,ppocr`, spaces around a name allowed; an option's value) and push their ids to `out`. 0, or `pkerr-unknown-engine` with the name in `msg`.
    let mut s: i32 = from;
    let mut i: i32 = from;
    let mut c: i32 = 44;
    let mut a: i32 = 0;
    let mut z: i32 = 0;
    let mut code: i32 = 0;
    while i <= to {
        c = 44;
        if i < to {
            c = crate::port::blob_u8(b, i);
        }
        if c == 44 {
            a = s;
            z = i;
            while (a < z) && (crate::port::blob_u8(b, a) == 32) {
                a += 1;
            }
            while (a < z) && (crate::port::blob_u8(b, z - 1) == 32) {
                z -= 1;
            }
            if z > a {
                code = eng_find(b, a, z);
                if code < 0 {
                    return pk_name_msg(msg, pkerr_unknown_engine(), b, a, z);
                }
                crate::port::cells_push(out, code);
            }
            s = i + 1;
        }
        i += 1;
    }
    return 0;
}
