pub fn pk_explain(code: i32, subject: &mut crate::port::Cells, mut msg: &mut String) -> i32 {
    // The sentence of a refusal of `pk-resolve` or `pk-record-engines`: the reason, then its subject (`subject` is what the call left in `out`).
    pkerr_emit_name(msg, code);
    if code == pkerr_unknown_engine() {
        crate::port::text_ascii(msg, ": ");
        crate::port::text_i32(msg, crate::port::cells_at(subject, 0));
    }
    if code == pkerr_unknown_pack() {
        crate::port::text_ascii(msg, ": ");
        crate::port::text_i32(msg, crate::port::cells_at(subject, 0));
    }
    if code == pkerr_unknown_class() {
        crate::port::text_ascii(msg, ": ");
        crate::port::text_i32(msg, crate::port::cells_at(subject, 0));
    }
    if code == pkerr_bad_language() {
        crate::port::text_ascii(msg, ": ");
        crate::port::text_i32(msg, crate::port::cells_at(subject, 0));
    }
    if (code == pkerr_not_ocr()) || (code == pkerr_engine_class()) {
        crate::port::text_ascii(msg, ": ");
        crate::port::text_cp(msg, 34);
        eng_emit_name(msg, crate::port::cells_at(subject, 0));
        crate::port::text_cp(msg, 34);
    }
    if code == pkerr_engine_class() {
        crate::port::text_ascii(msg, " on ");
        crate::port::text_cp(msg, 34);
        pcls_emit_name(msg, crate::port::cells_at(subject, 1));
        crate::port::text_cp(msg, 34);
    }
    return code;
}
